def shear(g):
    H=len(g);W=len(g[0])
    rows=[r for r in range(H) if any(g[r])]
    r0,r1=min(rows),max(rows)
    out=[[0]*W for _ in range(H)]
    for r in range(H):
        s=r1-r
        for c,v in enumerate(g[r]):
            if v and 0<=c-s<W: out[r][c-s]=v
    return out
